// Modèles des colosses (outils/blender-boss-a.py) : rempli par outils/pack_boss_a.py
window.GAME_ASSETS = window.GAME_ASSETS || { tex: {}, models: {}, kits: {} };
Object.assign(window.GAME_ASSETS.models, {"boss_beast":"data:model/gltf-binary;base64,","boss_hydra":"data:model/gltf-binary;base64,","boss_titan":"data:model/gltf-binary;base64,"});

/* BOSS_A_KIT(b, clé) : pièces nommées d'un modèle de boss, matériaux propres à ce combat (libérés par b.dispose).
   glow_* -> matériau lumineux du boss (couleur du stade) ; lava_* -> lueur douce qui suit la couleur du stade ;
   ooze_* -> lueur douce de couleur fixe ; le reste : copie du matériau Blender (flash blanc à l'impact). */
window.BOSS_A_KIT = function (b, key) {
  var BR = window.BR, g = BR && BR.Assets && BR.Assets.models[key];
  if (!g || !b.glowMat) return null;
  var mats = {}, soft = [], lava = [];
  function mat(m) {
    var n = (m && m.name) || '';
    if (/^glow/.test(n)) return b.glowMat;
    if (mats[n]) return mats[n];
    var c;
    if (/^(lava|ooze)/.test(n)) {
      c = new THREE.MeshStandardMaterial({ color: m.color.clone().multiplyScalar(0.25), emissive: m.color.clone(), emissiveIntensity: 1, roughness: 0.45, flatShading: m.flatShading });
      soft.push(c); if (/^lava/.test(n)) lava.push(c);
    } else { c = m.clone(); c.emissive = new THREE.Color(0); }
    c.name = n; mats[n.replace(/[^a-z0-9]/gi, '_')] = mats[n] = c; b.ownMats = (b.ownMats || []).concat([c]);
    return c;
  }
  function find(root, name) { var r = null; root.traverse(function (x) { if (!r && x.name === name) r = x; }); return r; }
  return {
    mats: mats, soft: soft, lava: lava,
    get: function (name) {
      var src = find(g.scene, name); if (!src) return null;
      var c = src.clone(true); c.position.set(0, 0, 0); c.rotation.set(0, 0, 0); c.scale.set(1, 1, 1);
      c.traverse(function (x) { if (x.isMesh) { x.material = Array.isArray(x.material) ? x.material.map(mat) : mat(x.material); x.castShadow = true; x.receiveShadow = true; } });
      return c;
    },
    node: find,
    // position d'origine (Blender) d'un nœud, relative à son parent
    src: function (name) { return find(g.scene, name); },
    flash: function (on) { for (var k in mats) { var m = mats[k]; if (soft.indexOf(m) < 0 && m.emissive) m.emissive.setScalar(on ? 0.09 : 0); } },
    // lueurs douces : la lave prend la couleur du stade, intensité k
    // photo découpée en disque (elle remplit le médaillon / le masque au lieu d'un carré)
    round: function (fm, r) {
      var m = fm && fm.material; if (!m || !m.isShaderMaterial || m.userData.round) return fm;
      m.fragmentShader = m.fragmentShader.replace('void main(){', 'void main(){ if (length(vUv - vec2(0.5)) > ' + (r || 0.5).toFixed(3) + ') discard;');
      m.userData.round = true; m.needsUpdate = true; return fm;
    },
    glow: function (col, k) { for (var i = 0; i < lava.length; i++) { lava[i].emissive.copy(col); lava[i].emissiveIntensity = k; } },
  };
};
